import random

GROUP = "geometry"
SKILL = "counting"


def generate(seed):
    rng = random.Random(seed)
    total_segments = rng.randint(3, 5)
    segment_length = rng.randint(10, 20)

    # Total number of segments minus the number of overlapping segments, with inclusion-exclusion for overlapping segments.
    total = total_segments
    overlapping_check = rng.randint(0, total_segments - 1)
    answer = total - overlapping_check

    # Independent route: count the number of non-overlapping segments by selecting them one by one and checking for overlaps.
    check = 0
    for i in range(total):
        for j in range(i + 1, total):
            if not segment_overlaps(i, j, segment_length):
                check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many non-overlapping segments of length {segment_length} can be placed along a line without any gaps? State only the integer."
    )
    return problem, str(answer)


def segment_overlaps(seg1, seg2, length):
    return not (seg2[1] <= seg1[0] or seg1[1] <= seg2[0])

