import random


def generate(seed):
    rng = random.Random(seed)

    beta = rng.choice([-9, -8, -7, -6, -5, -4, -3, -2, 2, 3, 4, 5, 6, 7, 8, 9])
    k = rng.randint(1, 12)
    c = rng.randint(-50, 50)

    # Define the piecewise function f(x) based on the absolute value equation
    # and count the number of solutions within the relevant intervals.
    def f(x):
        return abs((x + beta) ** 2 + (c - beta ** 2))

    # Determine the intervals where the function f(x) = k has solutions
    intervals = []
    disc1 = beta * beta - 4 * (c - k)
    disc2 = beta * beta - 4 * (c + k)
    if disc1 >= 0:
        if disc2 >= 0:
            intervals.append((1, 2))  # Two solutions in this interval
        else:
            intervals.append((0, 0))  # No solutions in this interval
    else:
        if disc2 >= 0:
            intervals.append((0, 0))  # No solutions in this interval
        else:
            intervals.append((1, 2))  # Two solutions in this interval

    answer = sum(intervals[i][1] for i in range(len(intervals)))

    # Independent route: solve both quadratics with the ordinary formula in
    # floating point and add up the squares of the distinct real solutions,
    # instead of deciding the case from upper and lower.
    solutions = []
    for constant in (c - k, c + k):
        disc = beta * beta - 4 * constant
        if disc < 0:
            continue
        root = math.sqrt(disc)
        solutions.append((-beta + root) / 2)
        if root > 0:
            solutions.append((-beta - root) / 2)
    check = sum(x * x for x in solutions)
    assert abs(check - answer) < 1e-6, f"answer={answer} check={check}"

    problem = (
        f"Let f(x) = |(x + {beta})^2 + ({c} - {beta}^2)|. How many real "
        f"solutions does the equation f(x) = {k} have? State only the integer."
    )

    return problem, str(answer)


