def generate(seed):
    rng = random.Random(seed)

    # INVARIANT: p, q, r are chosen such that their product remains equal to n
    n = rng.randint(100, 200)          # free parameter; widen freely
    p, q, r = sorted(rng.sample(range(1, n + 1), 3))
    while p * q * r != n:
        p, q, r = sorted(rng.sample(range(1, n + 1), 3))
    assert p * q * r == n, (
        "invariant violated: p, q, r must multiply to n"
    )

    # Constructing a brute-force approach to maximize the product p + q + r
    # without relying on the AM-GM inequality.
    max_sum = p + q + r

    # Independent route: search every combination of p, q, r that multiply to n.
    # Since we want to maximize the sum, we need to consider all factors of n.
    def find_max_sum(n):
        factors = set()
        for i in range(1, n + 1):
            if n % i == 0:
                factors.add(i)
        max_value = 0
        for p in factors:
            for q in factors:
                r = n // (p * q)
                if r in factors:
                    value = p + q + r
                    if value > max_value:
                        max_value = value
        return max_value

    check = find_max_sum(n)
    assert max_sum == check, f"max_sum={max_sum} check={check}"

    problem = (
        f"Let p, q, r be positive integers with p * q * r = {n}. "
        f"What is the maximum value of p + q + r?"
    )

    return problem, str(check)

