def generate(seed):
    rng = random.Random(seed)
    p = rng.randint(10, 100)  # Ensure p is a two-digit prime
    primes = [n for n in range(29, 101) if all(n % d for d in range(2, math.isqrt(n) + 1))]
    if p not in primes:
        p = rng.choice(primes)
    g = _primitive_root(p)
    a = pow(g, rng.randint(1, p - 2), p)
    k = rng.randint(1, 30)  # Limit k to avoid large exponents
    solutions = set()
    for x in range(p):
        if pow(x, k, p) == a:
            solutions.add(x)
    answer = len(solutions)

    check = len(solutions)
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let p = {p}, and let g = {g} be a primitive root modulo p. "
        f"For the residue a = {a}, how many residue classes x modulo {p} "
        f"satisfy x^{k} ≡ a (mod {p})?"
    )
    return problem, str(answer)

def _primitive_root(p):
    factors = sorted(_prime_factors(p - 1))  # sorted(): determinism rule
    for g in range(2, p):
        if all(pow(g, (p - 1) // q, p) != 1 for q in factors):
            return g
    return 2

def _prime_factors(n):
    factors = set()
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.add(d)
            n //= d
        d += 1
    if n > 1:
        factors.add(n)
    return factors

