    # without relying on the AM-GM inequality.
    max_product = (m + k) ** 3     # = ((s + 3k)/3)^3, exact since s = 3m

    # Independent route: search every combination of prime factors with the given sum.
    # Since 3 | s, the optimal values are equal prime factors, each giving the maximum product.
    def find_max_product(s, k):
        best_value = 0
        # Iterate over all possible prime factors a, b, c such that a + b + c = s
        for a in range(1, s - 1):
            for b in range(1, s - a):
                c = s - a - b
                # Ensure a, b, c are prime factors
                if all([is_prime(x) for x in [a, b, c]]):
                    value = (a + k) * (b + k) * (c + k)
                    if value > best_value:
                        best_value = value
        return best_value

    # Helper function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    check = find_max_product(s, k)
    assert max_product == check, f"max_product={max_product} check={check}"

    problem = (
        f"Let a, b, c be prime factors of a number N such that a + b + c = {s}. "
        f"Find the maximum value of (a + {k})(b + {k})(c + {k})."
    )

    return problem, str(check)

