        return total

    answer = count_non_divisible(n, primes)

    # Independent route: count the numbers using a simple loop to check divisibility
    check = 0
    for k in range(1, n + 1):
        if all(k % p != 0 for p in primes):
            check += 1
    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"How many integers k exist such that 1 <= k <= {n} and k is not divisible "
        f"by any of {primes[0]}, {primes[1]} and {primes[2]}? State only the integer."
    )
    return problem, str(answer)

import random

GROUP = "geometry"
SKILL = "counting"


def generate(seed):
    rng = random.Random(seed)
    side_length = rng.randint(10, 50)
    shape = rng.choice(['rectangle', 'circle', 'triangle'])

    # Define a function to check if a point is inside the specified shape
    if shape == 'rectangle':
        def is_inside(p):
            return p[0] <= x and p[1] <= y

    elif shape == 'circle':
        def is_inside(p):
            return (p[0] - x)**2 + (p[1] - y)**2 <= y**2

    elif shape == 'triangle':
        def is_inside(p):
            return p[0] <= x and p[1] <= y and p[0] + p[1] <= side_length

    # Count points inside the shape from 1 to (side_length + 1) * (side_length + 1)
    total_points = (side_length + 1) * (side_length + 1)
    points_inside = sum(1 for k in range(1, total_points + 1) if is_inside((k % (side_length + 1), k // (side_length + 1))))

    # Independent route: count the points inside the shape by checking each point individually
    check = 0
    for k in range(1, total_points + 1):
        if is_inside((k % (side_length + 1), k // (side_length + 1))):
            check += 1
    assert points_inside == check, f"points_inside={points_inside} check={check}"

    problem = (
        f"How many points (with integer coordinates) are inside the following shape: "
        f"{shape} with side length {side_length}, center at ({x}, {y})? State only the integer."
    )
    return problem, str(points_inside)

import random

GROUP = "number_theory"
SKILL = "counting"

def generate(seed):
    rng = random.Random(seed)
    primes = sorted(rng.sample([2, 3, 5, 7, 11, 13, 17, 19], 4))  # select 4 distinct primes
    e = rng.randint(50, 150)  # e is the exponent in the prime factorization

    # Calculate the number of integers less than or equal to e that are not divisible by any of the chosen primes.
    # This is the total number of integers minus the number that are divisible by at least one of the primes.
    total = e
    for prime in primes:
        total -= e // prime
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            total += e // (primes[i] * primes[j])
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                total -= e // (primes[i] * primes[j] * primes[k])
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                for l in range(k + 1, len(primes)):
                    total += e // (primes[i] * primes[j] * primes[k] * primes[l])

    # Independent route: test every integer in the range [1, e] to see if it is divisible by any of the chosen primes.
    check = sum(1 for k in range(1, e + 1) if all(k % prime != 0 for prime in primes))
    assert total == check, f"total={total} check={check}"

    problem = (
        f"How many integers less than or equal to {e} are **not** divisible by any of the primes {primes}? "
        f"State only the integer."
    )
    return problem, str(check)
